#!/usr/bin/env bash
cd "$(dirname "$0")"
PI=./bin/picture-it
run(){ id=$1; shift; ( s=$(date +%s); $PI "$@" -o gen/$id.png > logs/$id.out 2> logs/$id.err; echo "$id exit=$? $(( $(date +%s)-s ))s" | tee -a logs/times.log ) & }
run g6-kenny-v2 edit --model banana-pro -i ref/ref6.jpg -i src/anchor-1505-face.png -i src/sourced/iphone-colors.jpg --prompt "Create a 16:9 YouTube thumbnail photo. Copy the pose, framing and camera angle of Figure 1 only, never its person's face, glasses, or hair. The man is the man in Figure 2: keep his face exactly, including his age; do not widen, round, age, average, or blend it. He sits behind a large plain white table on the right half of the frame, his left forearm resting on the tabletop, and with his right arm he holds a light blue iPhone 18 Pro very close to the camera on the left side, so the phone appears huge in the foreground, tilted slightly, showing its back. The phone must copy Figure 3 exactly: the wide full-width raised camera plateau across the top of the back with three large lenses, the flat sides, and the exact light blue colour. Do not draw an older iPhone with a small square camera bump. He wears a plain black t-shirt and no glasses. Behind him, a dark navy wall with thick glowing light-blue maze-like circuit lines. At the top, the title 'iPhone 18 Pro' in huge bold glossy light-blue gradient sans-serif letters, with the man's head slightly overlapping the bottom of the letters."
run t2-aititle edit --model seedream --size 1280x720 -i work/t2-notitle.png --prompt "Add a YouTube thumbnail title on the right half of this image: the word 'INSIDE' in huge heavy bold white block capitals, and below it the word 'JEV' in huge heavy bold white block capitals on a slightly tilted solid red rectangle banner, and below that 'with the founder' in small spaced white monospace letters. Keep the man, his face, his hand, the microphone, the studio and the lighting exactly the same. Keep everything else exactly the same."
( s=$(date +%s); $PI remove-bg --model bria -i work/ply-g6v2-src.png -o gen/matte-bria-g6v2.png > logs/matte-bria.out 2> logs/matte-bria.err; echo "matte-bria exit=$? $(( $(date +%s)-s ))s" | tee -a logs/times.log ) &
wait
